def find_redundant_directed_connection(edges):
    n = len(edges)
    parent_of = [0] * (n + 1)
    cand1 = None
    cand2 = None
    for u, v in edges:
        if parent_of[v] != 0:
            cand1 = [parent_of[v], v]
            cand2 = [u, v]
        else:
            parent_of[v] = u
    dsu = list(range(n + 1))

    def find(x):
        while dsu[x] != x:
            dsu[x] = dsu[dsu[x]]
            x = dsu[x]
        return x

    for u, v in edges:
        if cand2 is not None and [u, v] == cand2:
            continue
        ru, rv = find(u), find(v)
        if ru == rv:
            if cand1 is not None:
                return cand1
            return [u, v]
        dsu[rv] = ru
    return cand2
